import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/material.dart';
import 'firebase_options.dart';
import 'screens/auth/splash_screen.dart';
import 'services/push_notification_service.dart';
import 'theme/tokens.dart';
import 'utils/nav_key.dart';
import 'utils/service_locator.dart';

void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  // Generated by `flutterfire configure` — carries the correct Firebase
  // project config for whichever platform (Android/iOS) this build runs on.
  await Firebase.initializeApp(options: DefaultFirebaseOptions.currentPlatform);

  // Must be registered before runApp so a push that arrives while the app
  // is backgrounded/killed is handled correctly.
  FirebaseMessaging.onBackgroundMessage(firebaseMessagingBackgroundHandler);

  ServiceLocator.init();

  // Sets up the local-notifications plugin (Android tray/lock-screen
  // display for foreground pushes, tap handling). Doesn't require login.
  await PushNotificationService.instance.initLocalNotifications();

  runApp(const AiraApp());
}

class AiraApp extends StatelessWidget {
  const AiraApp({super.key});

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      navigatorKey: navigatorKey,
      title: 'AiRA',
      debugShowCheckedModeBanner: false,
      theme: ThemeData(
        useMaterial3: true,
        scaffoldBackgroundColor: AiraColors.bg,
        colorScheme: ColorScheme.fromSeed(
          seedColor: AiraColors.rose,
          primary: AiraColors.rose,
          surface: AiraColors.bg,
        ),
        splashFactory: InkRipple.splashFactory,
      ),
      home: const SplashScreen(),
    );
  }
}
